<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Company');$cid=company_id($pdo);$iid=(int)($_GET['id']??$_POST['internship_id']??0);$s=$pdo->prepare('SELECT title FROM internship WHERE internship_id=? AND company_id=?');$s->execute([$iid,$cid]);$title=$s->fetchColumn();if(!$title)exit('Internship not found or not owned by your company.');$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$s=$pdo->prepare('INSERT INTO internship_skill(internship_id,skill_id,required_level) VALUES(?,?,?)');$s->execute([$iid,(int)($_POST['skill_id']??0),val('required_level',30)]);}catch(PDOException $e){$err='Skill already assigned or invalid.';}}
if(isset($_GET['remove'])){$s=$pdo->prepare('DELETE FROM internship_skill WHERE internship_id=? AND skill_id=?');$s->execute([$iid,(int)$_GET['remove']]);header('Location: internship_skills.php?id='.$iid);exit;}
$all=$pdo->query('SELECT skill_id,skill_name FROM skill ORDER BY skill_name')->fetchAll();$s=$pdo->prepare('SELECT sk.skill_id,sk.skill_name,ix.required_level FROM internship_skill ix JOIN skill sk ON sk.skill_id=ix.skill_id WHERE ix.internship_id=?');$s->execute([$iid]);$rows=$s->fetchAll();$b='<h2>Required skills: '.e($title).'</h2>'.($err?'<p class="error">'.e($err).'</p>':'').'<table><tr><th>Skill</th><th>Level</th><th>Action</th></tr>';
foreach($rows as $r)$b.='<tr><td>'.e($r['skill_name']).'</td><td>'.e($r['required_level']).'</td><td><a href="?id='.$iid.'&remove='.(int)$r['skill_id'].'">Remove</a></td></tr>';
$b.='</table><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="internship_id" value="'.$iid.'"><label>Skill<select name="skill_id">';foreach($all as $r)$b.='<option value="'.(int)$r['skill_id'].'">'.e($r['skill_name']).'</option>';$b.='</select></label><label>Level<select name="required_level"><option>Basic</option><option>Intermediate</option><option>Advanced</option><option>Expert</option></select></label><button>Add skill</button></form>';page('Required skills',$b);
